package com.DataExporter.exporters;

import com.DataExporter.DataExporterConfig;
import com.DataExporter.DataExporterPanel;
import com.DataExporter.util.ExportUtil;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import java.util.LinkedHashMap;
import java.util.Map;

public class CombatAchievementsExporter
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private DataExporterConfig config;
    @Inject private ExportUtil exportUtil;

    private static final Map<Integer, String> TIER_NAMES = new LinkedHashMap<>();
    private static final int[] VARP_IDS = {
        VarPlayerID.CA_TASK_COMPLETED_0,
        VarPlayerID.CA_TASK_COMPLETED_1,
        VarPlayerID.CA_TASK_COMPLETED_2,
        VarPlayerID.CA_TASK_COMPLETED_3,
        VarPlayerID.CA_TASK_COMPLETED_4,
        VarPlayerID.CA_TASK_COMPLETED_5,
        VarPlayerID.CA_TASK_COMPLETED_6,
        VarPlayerID.CA_TASK_COMPLETED_7,
        VarPlayerID.CA_TASK_COMPLETED_8,
        VarPlayerID.CA_TASK_COMPLETED_9,
        VarPlayerID.CA_TASK_COMPLETED_10,
        VarPlayerID.CA_TASK_COMPLETED_11,
        VarPlayerID.CA_TASK_COMPLETED_12,
        VarPlayerID.CA_TASK_COMPLETED_13,
        VarPlayerID.CA_TASK_COMPLETED_14,
        VarPlayerID.CA_TASK_COMPLETED_15,
        VarPlayerID.CA_TASK_COMPLETED_16,
        VarPlayerID.CA_TASK_COMPLETED_17,
        VarPlayerID.CA_TASK_COMPLETED_18,
        VarPlayerID.CA_TASK_COMPLETED_19,
    };

    static
    {
        TIER_NAMES.put(3981, "Easy");
        TIER_NAMES.put(3982, "Medium");
        TIER_NAMES.put(3983, "Hard");
        TIER_NAMES.put(3984, "Elite");
        TIER_NAMES.put(3985, "Master");
        TIER_NAMES.put(3986, "Grandmaster");
    }

    public JsonObject collect()
    {
        JsonObject allTiers = new JsonObject();

        for (Map.Entry<Integer, String> tier : TIER_NAMES.entrySet())
        {
            JsonArray tasks = new JsonArray();
            int tierCompleted = 0;

            EnumComposition e = client.getEnum(tier.getKey());
            for (int structId : e.getIntVals())
            {
                StructComposition struct = client.getStructComposition(structId);
                String name = struct.getStringValue(1308);
                int id = struct.getIntValue(1306);
                boolean completed = (client.getVarpValue(VARP_IDS[id / 32]) & (1 << (id % 32))) != 0;

                if (completed)
                {
                    tierCompleted++;
                }

                JsonObject task = new JsonObject();
                task.addProperty("name", name);
                task.addProperty("id", id);
                task.addProperty("completed", completed);
                tasks.add(task);
            }

            JsonObject tierObj = new JsonObject();
            tierObj.addProperty("completed", tierCompleted);
            tierObj.addProperty("total", tasks.size());
            tierObj.add("tasks", tasks);
            allTiers.add(tier.getValue(), tierObj);
        }

        return allTiers;
    }

    public String toCsv(JsonObject allTiers)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(ExportUtil.csvRow("Tier", "Tier Completed", "Tier Total", "Name", "ID", "Completed"));

        for (String tierName : allTiers.keySet())
        {
            JsonObject tier = allTiers.getAsJsonObject(tierName);
            String tierCompleted = tier.get("completed").getAsString();
            String tierTotal = tier.get("total").getAsString();

            for (var el : tier.getAsJsonArray("tasks"))
            {
                JsonObject task = el.getAsJsonObject();
                sb.append(ExportUtil.csvRow(
                    tierName,
                    tierCompleted,
                    tierTotal,
                    task.get("name").getAsString(),
                    task.get("id").getAsString(),
                    task.get("completed").getAsString()
                ));
            }
        }
        return sb.toString();
    }

    public void export(DataExporterPanel panel)
    {
        clientThread.invokeLater(() ->
        {
            JsonObject data = collect();
            JsonObject root = new JsonObject();
            root.add("combatAchievements", data);
            exportUtil.write("combat-achievements", config.format(), root, toCsv(data), client, panel);
        });
    }
}

package com.DataExporter.exporters;

import com.DataExporter.DataExporterConfig;
import com.DataExporter.DataExporterPanel;
import com.DataExporter.util.ExportUtil;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.swing.SwingUtilities;

public class BankExporter
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager itemManager;
    @Inject private DataExporterConfig config;
    @Inject private ExportUtil exportUtil;

    private Item[] cachedBankItems = new Item[0];

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.BANK.getId())
        {
            cachedBankItems = event.getItemContainer().getItems().clone();
        }
    }

    public boolean hasBankData()
    {
        return cachedBankItems.length > 0;
    }

    public JsonArray collect()
    {
        JsonArray bank = new JsonArray();
        for (Item item : cachedBankItems)
        {
            if (item == null || item.getId() == -1 || item.getQuantity() == 0)
            {
                continue;
            }
            ItemComposition comp = itemManager.getItemComposition(item.getId());
            JsonObject entry = new JsonObject();
            entry.addProperty("name", comp.getName());
            entry.addProperty("id", item.getId());
            entry.addProperty("quantity", item.getQuantity());
            bank.add(entry);
        }
        return bank;
    }

    public String toCsv(JsonArray bank)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(ExportUtil.csvRow("Name", "ID", "Quantity"));
        for (var el : bank)
        {
            JsonObject item = el.getAsJsonObject();
            sb.append(ExportUtil.csvRow(
                item.get("name").getAsString(),
                item.get("id").getAsString(),
                item.get("quantity").getAsString()
            ));
        }
        return sb.toString();
    }

    public void export(DataExporterPanel panel)
    {
        if (!hasBankData())
        {
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.setStatus("Open your bank in-game first!");
                }
            });
            return;
        }

        clientThread.invokeLater(() ->
        {
            JsonArray data = collect();
            JsonObject root = new JsonObject();
            root.add("bank", data);
            exportUtil.write("bank", config.format(), root, toCsv(data), client, panel);
        });
    }
}

