package com.DataExporter.exporters;

import com.DataExporter.DataExporterConfig;
import com.DataExporter.DataExporterPanel;
import com.DataExporter.model.DiaryArea;
import com.DataExporter.util.ExportUtil;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import java.util.LinkedHashMap;
import java.util.Map;

public class DiaryExporter
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private DataExporterConfig config;
    @Inject private ExportUtil exportUtil;

    public JsonObject collect()
    {
        Map<String, JsonObject> regions = new LinkedHashMap<>();

        for (DiaryArea area : DiaryArea.values())
        {
            regions.computeIfAbsent(area.getRegion(), k -> new JsonObject());
            boolean completed = client.getVarbitValue(area.getVarbitId()) == 1;
            String tierName = capitalize(area.getTier().name());
            regions.get(area.getRegion()).addProperty(tierName, completed);
        }

        JsonObject data = new JsonObject();
        for (Map.Entry<String, JsonObject> entry : regions.entrySet())
        {
            data.add(entry.getKey(), entry.getValue());
        }
        return data;
    }

    public String toCsv(JsonObject data)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(ExportUtil.csvRow("Region", "Tier", "Completed"));

        for (String region : data.keySet())
        {
            JsonObject tiers = data.getAsJsonObject(region);
            for (String tier : tiers.keySet())
            {
                sb.append(ExportUtil.csvRow(region, tier, tiers.get(tier).getAsString()));
            }
        }
        return sb.toString();
    }

    public void export(DataExporterPanel panel)
    {
        clientThread.invokeLater(() ->
        {
            JsonObject data = collect();
            JsonObject root = new JsonObject();
            root.add("diaries", data);
            exportUtil.write("diaries", config.format(), root, toCsv(data), client, panel);
        });
    }

    private static String capitalize(String s)
    {
        if (s == null || s.isEmpty())
        {
            return s;
        }
        return Character.toUpperCase(s.charAt(0)) + s.substring(1).toLowerCase();
    }
}

package com.DataExporter.exporters;

import com.DataExporter.DataExporterConfig;
import com.DataExporter.DataExporterPanel;
import com.DataExporter.util.ExportUtil;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;

@Slf4j
public class QuestsExporter
{
    private static final int VARPLAYER_QUEST_POINTS = 101;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private DataExporterConfig config;
    @Inject private ExportUtil exportUtil;

    public JsonObject collect()
    {
        JsonArray completed = new JsonArray();
        JsonArray inProgress = new JsonArray();
        JsonArray notStarted = new JsonArray();

        for (Quest quest : Quest.values())
        {
            QuestState state;
            try
            {
                state = quest.getState(client);
            }
            catch (Exception e)
            {
                log.warn("Could not get state for quest {}", quest.getName(), e);
                continue;
            }

            switch (state)
            {
                case FINISHED:
                    completed.add(quest.getName());
                    break;
                case IN_PROGRESS:
                    inProgress.add(quest.getName());
                    break;
                case NOT_STARTED:
                    notStarted.add(quest.getName());
                    break;
            }
        }

        JsonObject data = new JsonObject();
        data.addProperty("questPoints", client.getVarpValue(VARPLAYER_QUEST_POINTS));
        data.add("completed", completed);
        data.add("inProgress", inProgress);
        data.add("notStarted", notStarted);
        return data;
    }

    public String toCsv(JsonObject data)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(ExportUtil.csvRow("Quest Points", data.get("questPoints").getAsString()));
        sb.append(ExportUtil.csvRow("Name", "Status"));

        for (var el : data.getAsJsonArray("completed"))
        {
            sb.append(ExportUtil.csvRow(el.getAsString(), "Completed"));
        }
        for (var el : data.getAsJsonArray("inProgress"))
        {
            sb.append(ExportUtil.csvRow(el.getAsString(), "In Progress"));
        }
        for (var el : data.getAsJsonArray("notStarted"))
        {
            sb.append(ExportUtil.csvRow(el.getAsString(), "Not Started"));
        }
        return sb.toString();
    }

    public void export(DataExporterPanel panel)
    {
        clientThread.invokeLater(() ->
        {
            JsonObject data = collect();
            JsonObject root = new JsonObject();
            root.add("quests", data);
            exportUtil.write("quests", config.format(), root, toCsv(data), client, panel);
        });
    }
}

package com.DataExporter.exporters;

import com.DataExporter.DataExporterConfig;
import com.DataExporter.DataExporterPanel;
import com.DataExporter.util.ExportUtil;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class ClanExporter
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private DataExporterConfig config;
    @Inject private ExportUtil exportUtil;

    public JsonObject collect()
    {
        JsonArray members = new JsonArray();

        ClanSettings settings = client.getClanSettings();
        ClanChannel channel = client.getClanChannel();

        if (settings != null)
        {
            Set<String> onlineNames = new HashSet<>();
            if (channel != null)
            {
                for (ClanChannelMember member : channel.getMembers())
                {
                    onlineNames.add(member.getName());
                }
            }

            List<ClanMember> allMembers = settings.getMembers();
            if (allMembers != null)
            {
                for (ClanMember member : allMembers)
                {
                    JsonObject entry = new JsonObject();
                    entry.addProperty("name", member.getName());
                    entry.addProperty("online", onlineNames.contains(member.getName()));
                    members.add(entry);
                }
            }
        }

        JsonObject data = new JsonObject();
        if (settings != null)
        {
            data.addProperty("name", settings.getName());
        }
        data.add("members", members);
        return data;
    }

    public String toCsv(JsonObject data)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(ExportUtil.csvRow("Name", "Online"));
        for (var el : data.getAsJsonArray("members"))
        {
            JsonObject member = el.getAsJsonObject();
            sb.append(ExportUtil.csvRow(
                member.get("name").getAsString(),
                member.get("online").getAsString()
            ));
        }
        return sb.toString();
    }

    public void export(DataExporterPanel panel)
    {
        clientThread.invokeLater(() ->
        {
            JsonObject data = collect();
            JsonObject root = new JsonObject();
            root.add("clan", data);
            exportUtil.write("clan", config.format(), root, toCsv(data), client, panel);
        });
    }
}

package com.DataExporter;

import net.runelite.client.config.Config;
