@ConfigGroup("dataexporter")
public interface DataExporterConfig extends Config
{
    @ConfigItem(
        keyName = "format",
        name = "Export Format",
        description = "File format written on export"
    )
    default ExportFormat format()
    {
        return ExportFormat.JSON;
    }

    @ConfigItem(
        keyName = "combinedExport",
        name = "Combined File on Export All",
        description = "Export All writes one combined JSON file instead of separate files per category. Always JSON regardless of format setting."
    )
    default boolean combinedExport()
    {
        return false;
    }
}

