package com.DataExporter.util;

import com.DataExporter.DataExporterPanel;
import com.DataExporter.ExportFormat;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.Date;

@Slf4j
@Singleton
public class ExportUtil
{
    public static final File EXPORT_DIR = new File(System.getProperty("user.home"), ".runelite/data-exports");

    private final Gson gson;

    @Inject
    public ExportUtil(Gson gson)
    {
        this.gson = gson.newBuilder().setPrettyPrinting().create();
    }

    public void write(String type, ExportFormat format, JsonObject jsonData, String csvData, Client client, DataExporterPanel panel)
    {
        switch (format)
        {
            case JSON:
                writeJson(type, jsonData, client, panel);
                break;
            case CSV:
                writeCsv(type, csvData, client, panel);
                break;
            case BOTH:
                writeJson(type, jsonData, client, panel);
                writeCsv(type, csvData, client, panel);
                break;
        }
    }

    public void writeJson(String type, JsonObject data, Client client, DataExporterPanel panel)
    {
        String filename = buildFilename(type, client) + ".json";
        File file = new File(EXPORT_DIR, filename);

        try (FileWriter writer = new FileWriter(file))
        {
            gson.toJson(data, writer);
            log.info("Exported {} to {}", type, file.getAbsolutePath());
            setStatus(panel, "Exported: " + filename);
        }
        catch (IOException e)
        {
            log.error("Failed to export {}", type, e);
            setStatus(panel, "Error exporting " + type);
        }
    }

    public void writeCsv(String type, String csvData, Client client, DataExporterPanel panel)
    {
        String filename = buildFilename(type, client) + ".csv";
        File file = new File(EXPORT_DIR, filename);

        try (FileWriter writer = new FileWriter(file))
        {
            writer.write(csvData);
            log.info("Exported {} CSV to {}", type, file.getAbsolutePath());
            setStatus(panel, "Exported: " + filename);
        }
        catch (IOException e)
        {
            log.error("Failed to export {} CSV", type, e);
            setStatus(panel, "Error exporting " + type);
        }
    }

    public static String csvRow(String... fields)
    {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < fields.length; i++)
        {
            if (i > 0)
            {
                sb.append(',');
            }
            String f = fields[i] == null ? "" : fields[i].replace("\"", "\"\"");
            sb.append('"').append(f).append('"');
        }
        sb.append('\n');
        return sb.toString();
    }

    private static String buildFilename(String type, Client client)
    {
        String timestamp = new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss").format(new Date());
        String playerName = client.getLocalPlayer() != null
                ? client.getLocalPlayer().getName()
                : "unknown";
        return playerName + "_" + type + "_" + timestamp;
    }

    private static void setStatus(DataExporterPanel panel, String message)
    {
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.setStatus(message);
            }
        });
    }
}

package com.DataExporter;

import com.DataExporter.exporters.BankExporter;
import com.DataExporter.exporters.ClanExporter;
import com.DataExporter.exporters.CombatAchievementsExporter;
import com.DataExporter.exporters.DiaryExporter;
import com.DataExporter.exporters.FriendsExporter;
import com.DataExporter.exporters.IgnoresExporter;
import com.DataExporter.exporters.QuestsExporter;
import com.DataExporter.exporters.SkillsExporter;
import com.DataExporter.util.ExportUtil;
import com.google.gson.JsonObject;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import net.runelite.api.GameState;
import net.runelite.client.util.ImageUtil;
import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;

@PluginDescriptor(
        name = "Data Exporter",
        description = "Export player data to JSON/CSV files",
        tags = {"data", "export", "json", "csv", "skills", "quests", "bank", "diary", "task", "cas"}
)
public class DataExporterPlugin extends Plugin
{
    @Inject private net.runelite.api.Client client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private DataExporterConfig config;
    @Inject private ExportUtil exportUtil;

    @Inject private SkillsExporter skillsExporter;
    @Inject private QuestsExporter questsExporter;
    @Inject private BankExporter bankExporter;
    @Inject private FriendsExporter friendsExporter;
    @Inject private IgnoresExporter ignoresExporter;
    @Inject private ClanExporter clanExporter;
    @Inject private CombatAchievementsExporter combatAchievementsExporter;
    @Inject private DiaryExporter diaryExporter;

    private DataExporterPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp()
    {
        ExportUtil.EXPORT_DIR.mkdirs();
        eventBus.register(bankExporter);

        panel = new DataExporterPanel(this);
        navButton = NavigationButton.builder()
                .tooltip("Data Exporter")
                .icon(buildIcon())
                .priority(5)
                .panel(panel)
                .build();
        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown()
    {
        eventBus.unregister(bankExporter);
        clientToolbar.removeNavigation(navButton);
        panel = null;
    }

    public void exportSkills()             { if (isLoggedIn()) skillsExporter.export(panel); }
    public void exportQuests()             { if (isLoggedIn()) questsExporter.export(panel); }
    public void exportBank()               { if (isLoggedIn()) bankExporter.export(panel); }
    public void exportFriends()            { if (isLoggedIn()) friendsExporter.export(panel); }
    public void exportIgnores()            { if (isLoggedIn()) ignoresExporter.export(panel); }
    public void exportClan()               { if (isLoggedIn()) clanExporter.export(panel); }
    public void exportCombatAchievements() { if (isLoggedIn()) combatAchievementsExporter.export(panel); }
    public void exportDiaries()            { if (isLoggedIn()) diaryExporter.export(panel); }

    public void exportAll()
    {
        if (!isLoggedIn())
        {
            return;
        }

        if (config.combinedExport())
        {
            clientThread.invokeLater(() ->
            {
                JsonObject combined = new JsonObject();
                combined.add("skills", skillsExporter.collect());
                combined.add("quests", questsExporter.collect());
                combined.add("bank", bankExporter.collect());
                combined.add("friends", friendsExporter.collect());
                combined.add("ignores", ignoresExporter.collect());
                combined.add("clan", clanExporter.collect());
                combined.add("combatAchievements", combatAchievementsExporter.collect());
                combined.add("diaries", diaryExporter.collect());
                exportUtil.writeJson("export", combined, client, panel);
            });
        }
        else
        {
            exportSkills();
            exportQuests();
            exportBank();
            exportFriends();
            exportIgnores();
            exportClan();
            exportCombatAchievements();
            exportDiaries();
        }
    }

    private boolean isLoggedIn()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.setStatus("Not logged in.");
                }
            });
            return false;
        }
        return true;
    }

    @Provides
    DataExporterConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(DataExporterConfig.class);
    }

    private static BufferedImage buildIcon()
    {
        return ImageUtil.loadImageResource(DataExporterPlugin.class, "icon.png");
    }
}
